eval:return (async () => { const { s, w, g, res, sleep, maint, returned, me, know, dummy, castFreeze, clear, clearSky, sheathe, crowd, look } = await (async function () {
  const s = shards.session, w = s.world, g = shards.gameScene;
  const res = (r) => (r ? s.resource(r) : '');
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const maint = async (...commands) =>
    (await (await fetch('/__admin/maint', { method: 'POST', body: JSON.stringify({ commands }) })).json()).outputs;
  const returned = (out, kind) => ((out ?? '').match(new RegExp(`^: ${kind} (-?\\d+)`, 'm')) ?? [])[1];
  const me = w.player.id;
  const spell = (name) => w.spells.find((x) => res(x.object.nameRes) === name);
  // The spell, taught if the character hasn't it (an admin casts free)
  const know = async (name, sid) => {
    if (!spell(name)) await maint(`send object ${me} AddSpell num int ${sid} iability int 99 bDM int 1`);
    for (let i = 0; i < 50 && !spell(name); i++) await sleep(100);
    return spell(name);
  };
  // A training dummy on the square (row, col), placed there if there's none within a square and a half
  const dummy = async (rid, row, col) => {
    const x = (col - 0.5) * 1024, y = (row - 0.5) * 1024;
    const near = () =>
      [...w.objects.values()].find(
        (o) => /training dummy/i.test(res(o.info?.nameRes)) && Math.hypot(o.x - x, o.y - y) < 1.5 * 1024,
      );
    if (!near()) {
      const id = ((await maint('create object TrainingDummy'))[0].match(/Created object (\d+)/) ?? [])[1];
      const room = returned((await maint(`send object 0 FindRoomByNum num int ${rid}`))[0], 'OBJECT');
      await maint(
        `send object ${id} SetDontDispose`,
        `send object 0 UtilGoNearSquare what object ${id} where object ${room} new_row int ${row} new_col int ${col}`,
      );
      for (let i = 0; i < 50 && !near(); i++) await sleep(100);
    }
    return near();
  };
  // Hold time still: projectiles, sparks and the room stay as they are for the picture
  const run = g.frame.bind(g);
  const freeze = () => {
    g.frame = (dt, now) => run(0, now);
  };
  // Cast at a target and freeze once the projectile is `frac` of the way there (or `ms` after)
  const castFreeze = async (sp, target, { frac = null, ms = 350 } = {}) => {
    s.cast(sp.object.id, sp.numTargets ? [{ id: target }] : []);
    const t0 = performance.now();
    while (performance.now() - t0 < 3000) {
      await new Promise((r) => requestAnimationFrame(r));
      const p = [...w.projectiles.values()][0];
      if (frac === null ? performance.now() - t0 >= ms
        : p && Math.hypot(p.x - p.sourceX, p.y - p.sourceY) >= frac * Math.hypot(p.destX - p.sourceX, p.destY - p.sourceY)) break;
    }
    freeze();
  };
  // Creatures wandering by (rats, spiders) go to the far side of the room, out of the picture
  const clear = async (rid) => {
    const mine = w.objects.get(me);
    const room = returned((await maint(`send object 0 FindRoomByNum num int ${rid}`))[0], 'OBJECT');
    for (const o of [...w.objects.values()])
      if (o.id !== me && / (rat|spider|centipede|ant|snake)s? /i.test(res(o.info?.nameRes)) && Math.hypot(o.x - mine.x, o.y - mine.y) < 8 * 1024)
        await maint(`send object 0 UtilGoNearSquare what object ${o.id} where object ${room} new_row int 52 new_col int 12`);
    await sleep(1200);
    // any still near (a square it couldn't go to) leaves the room for good; the room makes more later
    for (const o of [...w.objects.values()])
      if (o.id !== me && /(rat|spider|centipede|ant|snake)s?/i.test(res(o.info?.nameRes)) && Math.hypot(o.x - mine.x, o.y - mine.y) < 8 * 1024)
        await maint(`send object ${o.id} Delete`);
    await sleep(800);
  };
  // The room's weather cleared (a storm thins the streets: ambientRooms.ts weatherScale)
  const clearSky = async (rid) => {
    const room = returned((await maint(`send object 0 FindRoomByNum num int ${rid}`))[0], 'OBJECT');
    await maint(`send object ${room} EndStorm`);
    for (let i = 0; i < 40 && w.effects.raining; i++) await sleep(250);
  };
  // The weapon put away, out of a first-person picture
  const sheathe = async () => {
    const held = returned((await maint(`send object ${me} GetWeapon`))[0], 'OBJECT');
    if (held) await maint(`send object ${me} TryUnuseItem what object ${held}`);
    await sleep(800);
  };
  // Wait (a while at most) for the room's crowd to come out
  const crowd = async (n, ms = 20000) => {
    const t0 = performance.now();
    while (performance.now() - t0 < ms && (g.ambientLife?.objects() ?? []).length < n) await sleep(500);
  };
  const look = (pitch) => {
    g.setViewMode('first');
    g.pitch = pitch;
  };
  return { s, w, g, res, sleep, maint, returned, me, know, dummy, castFreeze, clear, clearSky, sheathe, crowd, look };
})(); const d = await dummy(330, 37, 41); const sp = await know('fireball', 5); await sleep(2500); await castFreeze(sp, d.id, { frac: 0.3 }); })()

